contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 value, address other) public payable {
        require(other != address(0));
        require(other != address(this));

        address caller = address(this);
        uint256 beforeOther = c.balanceOf(other); if (__ESBMC_reverted()) return;
        uint256 beforeSelf = c.balanceOf(caller); if (__ESBMC_reverted()) return;
        uint256 beforeSupply = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterOther = c.balanceOf(other); if (__ESBMC_reverted()) return;
        uint256 afterSelf = c.balanceOf(caller); if (__ESBMC_reverted()) return;
        uint256 afterSupply = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool callerIsOther = (caller == other);

        assert(
            (reverted && afterOther == beforeOther && afterSelf == beforeSelf && afterSupply == beforeSupply) ||
            (!reverted && beforeSelf == value && afterSelf == 0 && afterSupply + value == beforeSupply && afterOther == beforeOther && !callerIsOther)
        );
    }

    receive() external payable {}
}

